using EqlTracker.Core;

static class CorrectPetRatingTests
{
    public static void Register(Action<string,Action> test)
    {
        void Test(string name,Action run)=>test("Pet rating repair · "+name,run);
        static void Check(bool value,string reason="Assertion failed"){if(!value)throw new Exception(reason);}
        static void Near(double expected,double? actual){Check(actual.HasValue&&Math.Abs(expected-actual.Value)<1e-9,$"Expected {expected}, got {actual}");}
        var c=new Catalog{Items=Json.Read<EquipmentSnapshot>(Path.Combine(AppContext.BaseDirectory,"data/equipment.json")).Items};
        var whip=c.Find("Revultant Whip")!;var evensong=c.Find("Evensong")!;var blood=c.Find("Bloodmoon")!;
        static LoadoutProfile Owner()=>new(){Classes=["SHD","BRD","MAG"],Level=50,PetType="Earth",PetLevel=50};
        PetBuild Build()=>new(){SlotConfigurationVersion=PetSlotPlanning.Version,DualWield=true,PetType="Earth",PetLevel=50,Items=[new(){Id="primary",Position=1,Slot="Storage",ItemKey=blood.Key,Name=blood.Name,Rank=4},new(){Id="secondary",Position=2,Slot="Storage",ItemKey=evensong.Key,Name=evensong.Name,Rank=5}]};
        LoadoutEvaluationSession Session(PetBuild b,Dictionary<string,double>? weights=null){var eq=PetEquipmentInference.Build(b,Owner(),c);return new(c,Owner(),true,new(weights??GearScorer.Defaults["Pet DPS"]),eq.Positions,eq.Positions,petInventory:b,effectivePetEquipment:eq);}
        Test("client values override only the exact observed ranks",()=>{var a=RankedItemStats.Resolve(whip,4);var b=RankedItemStats.Resolve(evensong,5);Near(7,a.Stats["Damage"]);Near(.5,a.Stats["Ratio"]);Near(16,b.Stats["Damage"]);Near(.64,b.Stats["Ratio"]);Check(a.Kind==ItemStatEvidenceKind.ClientObserved&&!a.WeaponUncertain&&b.Kind==ItemStatEvidenceKind.ClientObserved);Check(!RankedItemStats.Resolve(whip,5).WeaponUncertain&&!RankedItemStats.Resolve(evensong,4).WeaponUncertain&&RankedItemStats.Resolve(whip,5).Kind==ItemStatEvidenceKind.Estimated);});
        Test("all supplied attributes resists accuracy weight and bonus remain separate",()=>{var a=RankedItemStats.Resolve(whip,4);Near(9,a.Stats["DEX"]);Near(8,a.Stats["AGI"]);Near(9,a.Stats["ResistDisease"]);Near(9,a.Stats["ResistPoison"]);Near(4,a.Stats["ResistVoid"]);Near(.7,a.Weight);Near(10,a.Accuracy);Near(6,a.ObservedDamageBonus);Check(!a.Stats.ContainsKey("DamageBonus")&&!a.Stats.ContainsKey("Accuracy"));var b=RankedItemStats.Resolve(evensong,5);Near(1.7,b.Weight);Near(12.5,b.Accuracy);Near(12,b.ObservedDamageBonus);});
        Test("observations never rewrite catalog bases or extend to fractional XP",()=>{Near(5,whip.Stats["Damage"]);Near(11,evensong.Stats["Damage"]);Check(!whip.Stats.ContainsKey("ResistVoid"));Check(RankedItemStats.Resolve(whip,4,.5).Kind==ItemStatEvidenceKind.Estimated);var changed=EquipmentPositions.Copy(whip);changed.Stats["Damage"]=6;Check(RankedItemStats.Resolve(changed,4).Kind==ItemStatEvidenceKind.Estimated);});
        Test("missing damage does not create a zero ratio",()=>{var item=new ItemDefinition{Stats=new(){["Delay"]=20}};var p=RankedItemStats.Resolve(item,0);Check(!p.Stats.ContainsKey("Damage")&&!p.Stats.ContainsKey("Ratio"));});
        Test("ordinary scaling stays separate from disputed damage haste and negative stats",()=>{var p=RankedItemStats.Resolve(new(){Stats=new(){["AC"]=10,["HP"]=20,["Mana"]=10,["Endurance"]=20,["DEX"]=2,["ResistFire"]=5,["Haste"]=36,["STR"]=-5,["Damage"]=5,["Delay"]=14}},4);Near(14,p.Stats["AC"]);Near(28,p.Stats["HP"]);Near(14,p.Stats["Mana"]);Near(28,p.Stats["Endurance"]);Near(6,p.Stats["DEX"]);Near(9,p.Stats["ResistFire"]);Near(14,p.Stats["Delay"]);Check(p.UncertainStats.IsSupersetOf(new[]{"Haste","STR"})&&!p.WeaponUncertain&&!p.WeightIsBase);});
        Test("equipped Evensong Best compatible compares to itself",()=>{var b=Build();var eq=PetEquipmentInference.Build(b,Owner(),c);var result=PetEquipmentInference.Best(evensong,5,null,Session(b),eq.Positions)!;Check(result.Slot=="Secondary"&&result.CanCompare,result.Confidence);Near(0,result.Evaluation!.Unbuffed.Delta);Check(eq.Positions.Single(p=>p.Slot=="Range").Item==null);});
        Test("observed whip replacement reconciles minus 9.5 without changing custom weights",()=>{var b=Build();var result=Session(b).Present(whip,4,"SECONDARY:1");Near(-9.5,result.Evaluation!.Unbuffed.Delta);Near(-14,result.Evaluation.Unbuffed.Changes.Single(s=>s.Stat=="Ratio").Points);Near(4.5,result.Evaluation.Unbuffed.Changes.Single(s=>s.Stat=="DEX").Points);Near(result.Delta,result.Breakdown.Sum(s=>s.Points));Check(result.CanCompare&&result.Evaluation.WeaponNote.StartsWith("Current: Primary")&&!result.Evaluation.WeaponNote.Contains("planned"));var custom=new Dictionary<string,double>{{"DEX",2},{"Ratio",100}};Near(4,Session(b,custom).Compare(whip,4,"SECONDARY:1").Unbuffed.Delta);Near(2,custom["DEX"]);});
        Test("unchanged unverified Primary cancels from the known replacement",()=>{var b=Build();Check(!RankedItemStats.Resolve(blood,4).WeaponUncertain);Check(Session(b).Compare(whip,4,"SECONDARY:1").Status!="Conditional");});
        Test("adopted ranked replacements retain numeric arithmetic",()=>{var r=Session(Build()).Present(whip,5,"SECONDARY:1");Check(r.Evaluation!.Status!="Conditional"&&r.CanCompare);Near(-9,r.Evaluation.Unbuffed.Delta);Check(!r.Evaluation.Unbuffed.Notes.Any(n=>n.Contains("ranked-stat")));});
        Test("explicit physical move removes previous hand without mutating inventory",()=>{var b=Build();var original=System.Text.Json.JsonSerializer.Serialize(b);var r=Session(b).Compare(evensong,5,"PRIMARY:1",b.Items[1].Entry());Near(-(25d/28*100+7),r.Unbuffed.Delta);Check(r.Replaced.Count==2);Check(original==System.Text.Json.JsonSerializer.Serialize(b));});
        Test("distinct Lore copy cannot duplicate equipped Lore item",()=>{var b=Build();var other=b.Items[1].Entry();other.PhysicalId="pet:other";var r=Session(b).Compare(evensong,5,"PRIMARY:1",other);Check(r.Eligibility.StartsWith("LORE EQUIPPED")&&r.Unbuffed.Delta==null);});
        Test("a repeated physical reference equips once",()=>{var b=Build();var copy=EquipmentPositions.Copy(b.Items[1]);copy.Position=3;b.Items.Add(copy);var eq=PetEquipmentInference.Build(b,Owner(),c);Check(eq.Selections.Count(s=>s.EntryId==copy.Id)==1);});
        Test("Dual wield off excludes Secondary and does not leak it to Ranged",()=>{var b=Build();b.DualWield=false;var eq=PetEquipmentInference.Build(b,Owner(),c);Check(eq.Positions.Single(p=>p.Slot=="Secondary").Item==null&&eq.Positions.Single(p=>p.Slot=="Range").Item==null);Check(!Session(b).Fits(evensong,eq.Positions.Single(p=>p.Slot=="Secondary")));});
        Test("Ranged weapon ratio excluded from Pet totals but preserved for Self",()=>{var positions=new List<EquipmentPosition>{new(){Id="RANGE:1",Slot="Range",Knowledge=EquipmentKnowledge.Occupied,Item=new(){Name="Evensong +5",ConfirmedItemKey=evensong.Key}}};var p=new LoadoutEvaluationSession(c,Owner(),true,new(){{"Ratio",100}},positions,positions).CompareBuild(positions);Near(0,p.Unbuffed.CurrentScore);var s=new LoadoutEvaluationSession(c,Owner(),false,new(){{"Ratio",100}},positions,positions).CompareBuild(positions);Near(64,s.Unbuffed.CurrentScore);Check(Session(Build()).Compare(evensong,5,"RANGE:1").Eligibility=="Incompatible selected position");});
        Test("rank changes cache by actual rank and preserve inventory ranks",()=>{var b=Build();var session=Session(b);Near(-9.5,session.Compare(whip,4,"SECONDARY:1").Unbuffed.Delta);Check(session.Compare(whip,5,"SECONDARY:1").Status!="Conditional");Near(-9.5,session.Compare(whip,4,"SECONDARY:1").Unbuffed.Delta);Check(b.Items[1].Rank==5&&RankedItemStats.Resolve(whip,14).Kind==ItemStatEvidenceKind.Estimated);});
        Test("weapon line precedes Stats and grouped resists are concise",()=>{Check(Array.IndexOf(ItemStatGroups.Categories,"Weapons")<Array.IndexOf(ItemStatGroups.Categories,"Stats"));Check(ItemStatGroups.Category("Ratio")=="Weapons"&&ItemStatGroups.Category("Delay")=="Weapons");Check(RatingExplanation.GroupedLabel("ResistPoison")=="Poison"&&RatingExplanation.GroupedLabel("ResistDisease")=="Disease");});
        Test("heading identical to instruction is shown only once",()=>{var q=new QuestDefinition{Name="Bard Epic Quest"};var s=new QuestStep{Name="Talk to Konia Swiftfoot, receive a Torch of Misty.",Instructions="Talk to Konia Swiftfoot — receive a Torch of Misty"};var parts=QuestPresentation.Instruction(q,s);Check(parts.Heading==""&&parts.Instruction==s.Instructions);});
        Test("distinct headings and complete body remain intact",()=>{var s=new QuestStep{Name="Bard Epic Quest: Torch of Ro",Instructions="Give the torch to Fajio Knejo in Misty Thicket; receive Torch of Ro."};var parts=QuestPresentation.Instruction(new(){Name="Bard Epic Quest"},s);Check(parts.Heading=="Torch of Ro"&&parts.Instruction==s.Instructions);Check(QuestPresentation.Instruction(null,new(){Name="Gather scales"}).Heading=="Gather scales");});
        Test("pair comparisons use the same observed values",()=>{var pair=ItemPairComparison.Create(evensong,new(){Name="Evensong +5"},whip,4,null,Owner(),c);Near(.64,pair.Current.Stats["Ratio"]);Near(.5,pair.Candidate.Stats["Ratio"]);Check(pair.Warning.Length==0);});
        Test("equipment totals and optimization share observed projection",()=>{var b=Build();b.Items[0]=new(){Id="whip",Position=1,Slot="Primary",Name=whip.Name,ItemKey=whip.Key,Rank=4};b.Items[1].Slot="Secondary";var eq=PetEquipmentInference.Build(b,Owner(),c);Near(9,eq.Totals.Stats["DEX"]);Near(1.14,PetReassignment.Stats(eq,c)["Ratio"]);Check(eq.Totals.Weapons.Any(s=>s.Contains("ratio 0.5")));});
        Test("Default candidates retain manual Pet ranks without inventing player ownership",()=>{var b=Build();var stock=new InventorySnapshot();var copies=PetEquipmentInference.CandidateCopies(stock.Evidence(evensong),b,evensong);Check(copies.Count==1&&copies[0].Rank==5&&copies[0].PhysicalId=="pet:secondary"&&stock.Entries.Count==0);Check(PetEquipmentInference.CandidateCopies([],b,evensong,true).Count==0);var player=new InventoryEntry{Name="Evensong +5",Count=1,Location="Bank"};Check(PetEquipmentInference.CandidateCopies([player],b,evensong).Count==1);});
        Test("adding an already referenced physical Pet copy is rejected atomically",()=>{var b=Build();string before=System.Text.Json.JsonSerializer.Serialize(b);Check(!PetInventoryEditing.Add(b,evensong,b.Items[1].Entry(),7,null,false,out _,out var error)&&error.Contains("already"));Check(before==System.Text.Json.JsonSerializer.Serialize(b));});
        Test("per-field evidence distinguishes observed values from later catalog additions",()=>{var d=EquipmentPositions.Copy(evensong);d.Stats["HP"]=10;var projection=RankedItemStats.Resolve(d,5);Check(projection.StatEvidence["Damage"]==ItemStatEvidenceKind.ClientObserved&&projection.StatEvidence["HP"]==ItemStatEvidenceKind.Estimated);Near(15,projection.Stats["HP"]);});
        Test("transient copy identity preserves saved equipment fingerprints",()=>{var b=Build();var eq=PetEquipmentInference.Build(b,Owner(),c);var copy=EquipmentPositions.Copy(eq.Positions);Check(EquipmentPositions.Fingerprint(eq.Positions)==EquipmentPositions.Fingerprint(copy));Check(eq.Positions.Single(p=>p.Slot=="Secondary").Item!.PhysicalId=="pet:secondary"&&copy.Single(p=>p.Slot=="Secondary").Item!.PhysicalId=="");});
        Test("self comparison retains transferred-out intrinsic effects",()=>{var d=EquipmentPositions.Copy(evensong);d.Effects=["Proc: Example strike"];var catalog=new Catalog{Items=[d,blood]};var b=Build();b.Items[1].TransferredOutEffects=d.Effects.ToList();var eq=PetEquipmentInference.Build(b,Owner(),catalog);var session=new LoadoutEvaluationSession(catalog,Owner(),true,new(GearScorer.Defaults["Pet DPS"]),eq.Positions,eq.Positions,petInventory:b,effectivePetEquipment:eq);var result=PetEquipmentInference.Best(d,5,null,session,eq.Positions)!;Check(result.Evaluation!.EffectsGained.Count==0&&result.Evaluation.EffectsLost.Count==0);Near(0,result.Evaluation.Unbuffed.Delta);});
    }
}
